                        "顺带分清一对经常被混用的词:钱不是资本。钱是调动资源的票,资本是真能干活的工具。多印一沓票,岛上不会多一张网;融资新闻刷屏,也不等于新工具真被造出来。判断资本有没有变多,别数钱,数网、数船、数流水线。"
