                        "当然,价格不是永远诚实。恐慌、炒作、政策、垄断、信息不对称,都能让价格偏离现实。但反过来想:要是没有价格这套信号系统,大家更难知道资源到底稀缺在哪。股价、债券收益率、汇率、商品价格,都干着同样的报信工作。"
