                        "有趣的是,郁金香本身从头到尾没变,还是那颗球茎。变的只是人的预期。这就是价格会骗人的地方:平时它忠实地反映稀缺与否,可一旦所有人眼里只剩\u201c别人会不会出更高价\u201d,价格就和真实价值脱钩,被吹成泡沫。后面讲股市你会看到,同一个剧本在几百年里反复上演,只不过郁金香换成了股票、房子或者某个时髦概念。"
