                        "央行常常上新闻,但它不是给普通人办存款贷款的普通银行。它管的是更底层的东西:基础货币、短端利率、支付清算、金融稳定。要找一个形象的说法——央行是整个金融系统的水位调节器,拧的是总阀门。"
