                        "更深一层,美债收益率曲线还有一个“神算子”的本事:两年多期美债收益率高于十年期,专业说法叫“收益率倒挂”,历史上它几乎每次预示经济衰退都在提前应验——1989、2000、2007、2019、2022,每一次倒挂之后,两三年之内美国都进了衰退。为什么?因为倒挂意味着市场在说:眼前利率这么高,撑不了多久,后面得降。而“后面得降”的原因,往往就是经济已经扛不住了。倒挂不是衰退的原因,是市场聪明钱写在盘面上的衰退预告。"
