        "一条收益曲线摆在你面前,第一眼别盯着终点看“赚了多少钱”。先看它用了多长时间、中间最惨的时候跌过多深、每天颠簸到什么程度、有没有跑赢基准、背后扛了什么风险——这五件事分别对应五个不同的指标,谁也不能顶替谁。量化行业痴迷指标,不是因为公式好看,而是因为钱的体验是发生在时间里的:同样赚 20%,一路平稳爬上去,和先跌 50% 再挣扎回涨,是完全不同的两种人生。这一章把投资报告里最常见的收益风险指标,拆成你能看懂、能手算的零件,每个指标都配一道草稿纸上就能验证的小题,连同最容易踩进去的误区一起摆上桌。",
