                    "评价策略不能光看赚了多少,还得问:这份收益是背着多大的晃荡换来的?夏普比率干的就是这笔除法:(组合收益 - 无风险收益) / 组合波动率。机制上为什么非要先扣无风险利率?因为那是地板收益:买点货币基金或短债,不承担任何波动也能拿到。把它从分子里剔掉,剩下的才是你扛晃荡换来的报酬;不扣的话,钱的时间价值会被错记成你冒险的功劳。想清这一步,夏普才不是一道好看的除法,而是“超额报酬除以代价”的诚实账。"
