                    "新手打听策略,最爱问的一句是“胜率多少”。胜率高听着确实舒服,但它单独什么也证明不了。算一笔极端的账:某策略 90% 的交易每次赚 1 元,10% 的交易每次亏 20 元,胜率九成、风光无限。算期望:0.9 乘 1 加 0.1 乘 -20,等于 -1.1,平均每笔亏 1.1 元;换成 10 笔反算验证,9 笔共赚 9 元,1 笔亏 20 元,净亏 11 元,除以 10 恰是 -1.1。账目自洽,结论扎心:经常赢,和长期赚,是两码事。"
