                    "树模型在表格数据上常年能打,所以量化股票的截面数据里也到处是它: 不挑特征尺度,对异常值相对稳健,还能顺手输出特征重要性。很多中低频量化研究会拿梯度提升树当强基线——新模型要是连这个基线都打不过,就先别谈上线。"
