                    "真正的工夫全在规则之外:用哪个连续合约算?什么时候换月?信号出在收盘,下一根 K 线成交还是当天成交?手续费和滑点扣多少?保证金怎么计算?涨跌停无法成交怎么办?夜盘数据怎么和白盘合并?这些细节每一项都不起眼,每一项都能把回测写成另一份回测。"
