            ("期货保证金为什么会放大风险?", "因为你只用较少的保证金就控制了较大名义价值的合约,标的的小幅波动,会被杠杆放大成本金的大幅波动。"),
            ("期货回测为什么不能随便拼接合约价格?", "不同到期合约的价格和流动性不同,换月会产生跳变;必须先明确连续合约口径和真实成交口径的换算关系。"),
            ("趋势跟踪为什么胜率不高仍然可能赚钱?", "它可以经常小亏,靠少数持续大趋势贡献较大盈利——赚的是盈亏比,不是高胜率。"),
            ("CTA 为什么不是股票下跌保险?", "它和股票收益来源不同、相关性可能较低,但危机中也可能因趋势不连续、快速反转或流动性冲击而同步亏损。"),
