                    "一只组合涨的时候跟着大盘涨、跌的时候跟着大盘跌,这叫什么?这叫身上有 Beta。Beta 说的是你的组合对市场或某类风险暴露的敏感度:股票组合 Beta 接近 1,意思是它大体跟市场同涨同跌;Beta 接近 0,则市场往哪边走,对它影响都不大。"
