            "雪球的两位数票息来自你卖出的看跌保护:涨够敲出、收益封顶,跌穿敲入、按指数跌幅结账;敲入线附近,做市商的对冲盘会反向加速下跌,2022 年与 2024 年初的大面积敲入就是这么来的。",
